import i18next from "i18next";
import { readdirSync, readFileSync } from "node:fs";
import { basename, join } from "node:path";

import en from "@/i18n/en.json";

// Whether every language the app offers actually renders text.
//
// This exists because it did not. The German and French catalogues are
// generated by `sync-i18n`, which fills each untranslated key with an empty
// string, and i18next returns "" as a valid translation rather than falling
// back. 148 of 168 keys in each were empty, so choosing German or French from
// the language selector produced a mostly blank interface -- buttons with no
// label, headings with no text. Keys that were MISSING entirely fell back to
// English and looked fine, which is what made the failure so uneven.
//
// The contract asserted here is the user-visible one: for every key the app
// can ask for, in every language it offers, something readable comes back. How
// that happens -- a real translation or a fallback -- is not this test's
// business, which is why it drives i18next rather than comparing files.

const LOCALE_DIR = join(__dirname, "..", "src", "i18n");

/** Every translation key, flattened to dotted paths. */
function keyPaths(value: unknown, prefix = ""): string[] {
  if (value === null || typeof value !== "object") {
    return [prefix];
  }
  return Object.entries(value).flatMap(([key, inner]) =>
    keyPaths(inner, prefix === "" ? key : `${prefix}.${key}`),
  );
}

const locales = readdirSync(LOCALE_DIR)
  .filter((file) => file.endsWith(".json"))
  .map((file) => ({
    name: basename(file, ".json"),
    translation: JSON.parse(
      readFileSync(join(LOCALE_DIR, file), "utf8"),
    ) as Record<string, unknown>,
  }));

const englishKeys = keyPaths(en);

beforeAll(async () => {
  await i18next.init({
    fallbackLng: "en",
    lng: "en",
    resources: Object.fromEntries(
      locales.map(({ name, translation }) => [name, { translation }]),
    ),
    // The configuration under test: without it, an empty translation is
    // returned as-is and the interface goes blank.
    returnEmptyString: false,
  });
});

it("ships more than one language", () => {
  // Guards the guard: if the locale directory were ever emptied or moved, the
  // per-language checks below would vacuously pass.
  expect(locales.length).toBeGreaterThan(1);
  expect(locales.map(({ name }) => name)).toContain("en");
});

it("has keys to check", () => {
  expect(englishKeys.length).toBeGreaterThan(100);
});

describe.each(locales.map(({ name }) => name))("%s", (locale) => {
  it("renders non-empty text for every key the app can ask for", () => {
    const translate = i18next.getFixedT(locale);
    const blank = englishKeys.filter((key) => {
      const value = translate(key);
      return typeof value !== "string" || value.trim() === "";
    });

    // Naming the keys rather than counting them: a failure here should say
    // which controls would render blank, not merely that some would.
    expect(blank).toEqual([]);
  });

  it("resolves every key to a string, never to the key itself", () => {
    const translate = i18next.getFixedT(locale);
    // i18next returns the key when it can find nothing at all, which on screen
    // looks like debug output leaking into the interface.
    const unresolved = englishKeys.filter((key) => translate(key) === key);

    expect(unresolved).toEqual([]);
  });

  it("defines no key that English does not", () => {
    const extra = keyPaths(
      locales.find((entry) => entry.name === locale)?.translation ?? {},
    ).filter((key) => !englishKeys.includes(key));

    // A key only a translation defines is unreachable: nothing asks for it,
    // and it will drift further from English with every change.
    expect(extra).toEqual([]);
  });
});
